/* ============================================================================
   MSG-01 · Lista de Hilos — panel de contenido.
   El shell (brand bar, nav bar, sidebar y VERA) no se toca: esto es solo el
   contenido que se monta dentro de .bwcnt.
   ========================================================================== */

.panel {
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-brand); /* el HTML aprobado usa 10px */
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin: 0 0 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin: 0 0 3px;
}

.subtitle {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin: 0 0 16px;
  max-width: 560px;
}

.e2ee {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-brand);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-brand);
  color: var(--bw-signal-green);
  margin-bottom: 14px;
  padding: 6px 10px;
  /* El HTML usa rgba(22,163,74,.06)/.15; los tokens del badge success son
     .08/.2 — el verde de éxito de la paleta. */
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  width: fit-content;
}

.e2ee i {
  font-size: var(--bw-size-label);
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchWrap {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: var(--bw-size-input);
  color: var(--bw-deep-steel);
  outline: none;
  font-family: inherit;
  /* El HTML usa `background: white`; surface-mist es la superficie clara más
     cercana de la paleta y se distingue del Cold White del panel. */
  background: var(--bw-surface-mist);
  transition: border-color 0.15s;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.primaryBtn {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  /* Texto sobre azul primario: `--bw-cold-white` es el "blanco" más cercano
     de la paleta. */
  color: var(--bw-cold-white);
  font-size: var(--bw-size-input);
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  transition: opacity 0.12s;
}

.primaryBtn:hover:not(:disabled) {
  opacity: 0.88;
}

.primaryBtn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.threadCount {
  font-size: var(--bw-size-label);
  color: var(--bw-input-placeholder);
  margin-left: auto;
  white-space: nowrap;
}

.centerState {
  padding: 48px 20px;
  text-align: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  color: var(--bw-ink-steel-soft);
  font-size: var(--bw-size-body);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.errorBox {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px;
  border-radius: 5px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  color: var(--bw-error-text);
  font-size: var(--bw-size-input);
}

.emptyState {
  padding: 48px 20px;
  text-align: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  color: var(--bw-ink-steel-soft);
  font-size: var(--bw-size-body);
  line-height: 1.6;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  /* Sustituto de `white` del HTML, como en la lista y el input. */
  background: var(--bw-surface-mist);
  font-size: var(--bw-size-label);
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  transition: all 0.12s;
}

.pageBtn:hover:not(:disabled):not(.act) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: 1px;
}

.pageBtn:disabled {
  cursor: default;
}

.act {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-cold-white);
  cursor: default;
}

.ctrl {
  color: var(--bw-input-placeholder);
}

.pageEllipsis {
  min-width: 30px;
  height: 30px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bw-input-placeholder);
  font-size: var(--bw-size-label);
}

