import { useEffect, useState, type KeyboardEvent } from 'react';
import type { MemberProfile } from '../../lib/session';
import {
  fetchThreadPage,
  pageCount,
  sanitizeSearch,
  type ThreadPage,
} from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

/**
 * MSG-01 · Lista de Hilos — la pantalla, no un componente de presentación.
 *
 * Posee el estado de búsqueda y de página, llama a `fetchThreadPage` y decide
 * entre carga / error / vacío / lista. El orden de los hilos es del servidor
 * (`last_item_at` descendente) y la búsqueda filtra al pulsar Enter (spec §3).
 *
 * Congelación del corpus (F-118, decidido por el PO el 28-ago-2026):
 * `onOpenThread` la pasa el shell desde `App.tsx`, que se cableó DESPUÉS de
 * escribirse esta tarea (para MSG-02). Se declara porque es la firma pública
 * del componente y sin ella el repo no compila — el fallo salía en `App.tsx`,
 * un fichero que no se escribe aquí. Se recibe y se IGNORA: MSG-02 no existía
 * cuando se escribió esta tarea y abrir un hilo no lleva a ningún sitio.
 */
interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  onOpenThread?: (threadId: string) => void;
}

// MSG-02 no está entre las 8 pantallas del MVP (Plan §9): el ThreadList avisa
// con el id del hilo y esta pantalla lo descarta. Un no-op explícito, no un
// onClick que parezca navegar (F-023 e).
const noop = (): void => undefined;

/** Ventana de páginas para la paginación: 1 … p-1 p p+1 … N (server-side). */
function pageNumbers(current: number, total: number): Array<number | '…'> {
  if (total <= 7) {
    return Array.from({ length: total }, (_, i) => i + 1);
  }
  const set = new Set<number>([1, total, current - 1, current, current + 1]);
  const sorted = [...set].filter((p) => p >= 1 && p <= total).sort((a, b) => a - b);
  const out: Array<number | '…'> = [];
  let prev = 0;
  for (const p of sorted) {
    if (p - prev > 1) out.push('…');
    out.push(p);
    prev = p;
  }
  return out;
}

export function Messages({ profile, now = new Date(), onOpenThread }: MessagesProps) {
  // F-118: la prop llega cableada desde App.tsx y esta pantalla no tiene
  // destino al que abrir el hilo (MSG-02 fuera del alcance). Se ignora.
  void onOpenThread;

  const [draft, setDraft] = useState('');
  const [query, setQuery] = useState('');
  const [page, setPage] = useState(1);
  const [data, setData] = useState<ThreadPage | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search: query, page })
      .then((result) => {
        if (cancelled) return;
        setData(result);
      })
      .catch(() => {
        if (cancelled) return;
        setError('No se pudieron cargar los hilos. Inténtalo de nuevo.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, query, page]);

  const submitSearch = () => {
    const term = sanitizeSearch(draft);
    if (term === query) return;
    setQuery(term);
    setPage(1);
  };

  const handleSearchKeyDown = (e: KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      submitSearch();
    }
  };

  const totalPages = data ? pageCount(data.total) : 1;
  const pages = pageNumbers(page, totalPages);

  return (
    <div className={styles.panel}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a extremo.
      </p>

      {/* El MVP no tiene passphrase (CLAUDE.md §4): las claves viven en memoria
          de sesión. La barra es solo informativa; el botón «Introducir frase de
          seguridad» del mock no se pinta como acción disponible (F-023 e). */}
      <div className={styles.e2ee}>
        <i className="ti ti-lock" aria-hidden="true" />
        E2EE activo · claves en memoria de sesión · contenido descifrado localmente
      </div>

      <div className={styles.actionsBar}>
        <div className={styles.searchWrap}>
          <i className={`ti ti-search ${styles.searchIcon}`} aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={handleSearchKeyDown}
          />
        </div>
        {/* «Nuevo contacto» abre DIR-01, que no está entre las 8 pantallas del
            alcance (Plan §9): el control existe pero no lleva a ninguna parte.
            Se pinta deshabilitado con el motivo, como el botón de subida de
            INV-01 (F-023 e). */}
        <button
          type="button"
          className={styles.primaryBtn}
          disabled
          title="El Directorio (DIR-01) estará disponible en una próxima versión."
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        {data ? (
          <span className={styles.threadCount}>
            {data.total.toLocaleString('es-ES')} {data.total === 1 ? 'hilo' : 'hilos'} · Página {page} de{' '}
            {totalPages}
          </span>
        ) : null}
      </div>

      {loading && data === null ? (
        <div className={styles.centerState} role="status">
          Cargando hilos…
        </div>
      ) : error ? (
        /* F-127: el aviso de error lleva role="alert" — el contrato lo busca
           por su papel, no por su texto. Carga y vacío no lo llevan. */
        <div className={styles.errorBox} role="alert">
          <i className="ti ti-alert-triangle" aria-hidden="true" />
          <span>{error}</span>
        </div>
      ) : data && data.threads.length === 0 ? (
        <div className={styles.emptyState}>
          <p>
            {query
              ? `No se encontraron hilos para «${query}».`
              : 'Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.'}
          </p>
          {!query ? (
            <button
              type="button"
              className={styles.primaryBtn}
              disabled
              title="El Directorio (DIR-01) estará disponible en una próxima versión."
            >
              <i className="ti ti-building" aria-hidden="true" />
              Ir al Directorio
            </button>
          ) : null}
        </div>
      ) : data ? (
        <>
          <ThreadList threads={data.threads} now={now} onOpen={noop} />
          <div className={styles.pagination}>
            <button
              type="button"
              className={`${styles.pageBtn} ${styles.ctrl}`}
              disabled={page <= 1}
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              aria-label="Página anterior"
            >
              ‹
            </button>
            {pages.map((p, i) =>
              p === '…' ? (
                <span key={`gap-${i}`} className={styles.pageEllipsis}>
                  …
                </span>
              ) : (
                <button
                  key={p}
                  type="button"
                  className={`${styles.pageBtn} ${p === page ? styles.act : ''}`}
                  aria-current={p === page ? 'page' : undefined}
                  onClick={() => setPage(p)}
                >
                  {p}
                </button>
              ),
            )}
            <button
              type="button"
              className={`${styles.pageBtn} ${styles.ctrl}`}
              disabled={page >= totalPages}
              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
              aria-label="Página siguiente"
            >
              ›
            </button>
          </div>
        </>
      ) : null}
    </div>
  );
}

