/* ============================================================================
   MSG-01 · Lista de Hilos — filas de la lista.
   ========================================================================== */

.list {
  /* El HTML aprobado usa `background: white`. La paleta no define blanco puro:
     surface-mist (#F8F9FB) es la superficie clara más cercana y, sobre el
     fondo Cold White del panel, la tarjeta sigue distinguiéndose. */
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  appearance: none;
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  border: none;
  border-radius: 0;
  border-bottom: 1px solid var(--bw-divider-mist);
  background: none;
  font-family: inherit;
  text-align: left;
  color: inherit;
  cursor: pointer;
  transition: background 0.1s;
}

.row:last-child {
  border-bottom: none;
}

.row:hover {
  background: var(--bw-row-hover-tint);
}

.row:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.top {
  display: flex;
  align-items: center;
  gap: 8px;
}

.org {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.country {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
}

.tsRow {
  display: flex;
  align-items: center;
  gap: 6px;
  justify-content: flex-end;
}

.ts {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  /* El HTML aprobado usa #9BA4B0, que es el valor de --bw-input-placeholder. */
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.bottom {
  display: flex;
  align-items: center;
  gap: 8px;
}

.preview {
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

/* ABIERTO */
.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

/* CON CONSULTA PENDIENTE — el HTML usa rgba(37,99,235,.2) de borde; el token
   de borde azul de la paleta es --bw-chip-active-border (0.3). */
.info {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

/* CON OFERTA PENDIENTE */
.warn {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

/* ACUERDO ALCANZADO */
.success {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

/* CERRADO SIN ACUERDO — el HTML usa #9BA4B0 para el texto; el token del gris
   más tenue (texto deshabilitado) es --bw-hint-steel. */
.closed {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-hint-steel);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

