import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

/**
 * MSG-01 · Lista de Hilos — componente de presentación.
 *
 * Pinta las filas en el orden en que las recibe: el orden es del servidor
 * (`fetchThreadPage` ordena por `last_item_at` descendente). No carga datos,
 * no pagina y no reordena.
 *
 * Cada fila es un botón que avisa con el **id** del hilo, no con el objeto.
 *
 * La vista previa son metadatos únicamente (`previewLabel`): el spec §7 prohíbe
 * mostrar contenido descifrado en esta pantalla. Tampoco hay indicador de
 * no leídos: el esquema no tiene seguimiento de lectura, así que un recuento
 * sería un número inventado delante del socio (F-027).
 */
interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  onOpen: (id: string) => void;
}

const TONE_CLS: Record<StateTone, string> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  return (
    <div className={styles.list}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        return (
          <button
            type="button"
            key={thread.id}
            className={styles.row}
            onClick={() => onOpen(thread.id)}
            aria-label={`Abrir hilo con ${thread.counterpartyName}`}
          >
            <span className={styles.top}>
              <span className={styles.org}>{thread.counterpartyName}</span>
              {thread.counterpartyCountry ? (
                <span className={styles.country}>{thread.counterpartyCountry}</span>
              ) : null}
            </span>
            <span className={styles.tsRow}>
              <span className={styles.ts}>{relativeTime(thread.lastItemAt, now)}</span>
            </span>
            <span className={styles.bottom}>
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
              <span className={`${styles.stateBadge} ${TONE_CLS[tone]}`}>{thread.state}</span>
            </span>
            <span aria-hidden="true" />
          </button>
        );
      })}
    </div>
  );
}
